{"version":3,"file":"ui-planning.min.js","sources":["../../../src/local/courseai/ui-planning.js"],"sourcesContent":["// This file is part of Moodle - http://moodle.org/\n//\n// Moodle is free software: you can redistribute it and/or modify\n// it under the terms of the GNU General Public License as published by\n// the Free Software Foundation, either version 3 of the License, or\n// (at your option) any later version.\n//\n// Moodle is distributed in the hope that it will be useful,\n// but WITHOUT ANY WARRANTY; without even the implied warranty of\n// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n// GNU General Public License for more details.\n//\n// You should have received a copy of the GNU General Public License\n// along with Moodle.  If not, see <http://www.gnu.org/licenses/>.\n\n/**\n * Planning UI helpers — orchestrator.\n *\n * Re-exports setCompactChatState so existing importers remain unaffected,\n * and assembles the full createPlanningUi factory from focused submodules.\n *\n * @module     local_coursegen/local/courseai/ui-planning\n * @copyright  2026 Wilber Narvaez <https://datacurso.com>\n * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later\n */\n\nexport { setCompactChatState } from './planning/compact-chat';\nimport { addPlanSection, addActivityToSection } from './planning/render';\nimport { showReviewActions } from './planning/review-actions';\nimport { setCompactChatState as setCompactChatStateImpl } from './planning/compact-chat';\n\n/**\n * Create planning UI helpers.\n *\n * @param {Object} deps\n * @returns {Object}\n */\nexport const createPlanningUi = (deps) => {\n    const {\n        state,\n        elements,\n        activityLabels,\n        getActivityIconUrl,\n        escapeHtml,\n        setProgress,\n        texts,\n        formatTemplate,\n    } = deps;\n\n    const {\n        prvSections,\n        prvHeaderSub,\n        planReviewCard,\n    } = elements;\n\n    /**\n     * Sync main-chat state (language, chips) into the compact-chat panel.\n     */\n    const syncCompactChatState = () => {\n        // Sync language\n        const langSelect = document.getElementById('langSelect');\n        const compactLangSelect = document.getElementById('compactLangSelect');\n        if (langSelect && compactLangSelect) {\n            compactLangSelect.value = langSelect.value;\n        }\n\n        // Sync images toggle\n        const btnWithImages = document.getElementById('btnWithImages');\n        const btnCompactWithImages = document.getElementById('btnCompactWithImages');\n        const imgToggleTrack = document.getElementById('imgToggleTrack');\n        const compactImgToggleTrack = document.getElementById('compactImgToggleTrack');\n        if (btnWithImages && btnCompactWithImages) {\n            btnCompactWithImages.checked = btnWithImages.checked;\n            if (compactImgToggleTrack && imgToggleTrack) {\n                if (btnWithImages.checked) {\n                    compactImgToggleTrack.parentElement.classList.add('on');\n                } else {\n                    compactImgToggleTrack.parentElement.classList.remove('on');\n                }\n            }\n        }\n\n        // Sync subsections toggle\n        const btnWithSubsections = document.getElementById('btnWithSubsections');\n        const btnCompactWithSubsections = document.getElementById('btnCompactWithSubsections');\n        const subToggleTrack = document.getElementById('subToggleTrack');\n        const compactSubToggleTrack = document.getElementById('compactSubToggleTrack');\n        if (btnWithSubsections && btnCompactWithSubsections) {\n            btnCompactWithSubsections.checked = btnWithSubsections.checked;\n            if (compactSubToggleTrack && subToggleTrack) {\n                if (btnWithSubsections.checked) {\n                    compactSubToggleTrack.parentElement.classList.add('on');\n                } else {\n                    compactSubToggleTrack.parentElement.classList.remove('on');\n                }\n            }\n        }\n\n        // Sync syllabus chip\n        const chipSyllabus = document.getElementById('chipSyllabus');\n        const compactChipSyllabus = document.getElementById('compactChipSyllabus');\n        const chipSyllabusName = document.getElementById('chipSyllabusName');\n        const compactChipSyllabusName = document.getElementById('compactChipSyllabusName');\n        const compactChipsRow = document.getElementById('compactChipsRow');\n        if (chipSyllabus && compactChipSyllabus && chipSyllabusName && compactChipSyllabusName) {\n            if (!chipSyllabus.classList.contains('hidden')) {\n                compactChipSyllabus.classList.remove('hidden');\n                compactChipSyllabusName.textContent = chipSyllabusName.textContent;\n                if (compactChipsRow) {\n                    compactChipsRow.style.display = 'flex';\n                }\n            } else {\n                compactChipSyllabus.classList.add('hidden');\n            }\n        }\n\n        // Sync guideline chip\n        const chipGuideline = document.getElementById('chipGuideline');\n        const compactChipGuideline = document.getElementById('compactChipGuideline');\n        const chipGuidelineName = document.getElementById('chipGuidelineName');\n        const compactChipGuidelineName = document.getElementById('compactChipGuidelineName');\n        const guidelineBadge = document.getElementById('guidelineBadge');\n        const compactGuidelineBadge = document.getElementById('compactGuidelineBadge');\n        if (chipGuideline && compactChipGuideline && chipGuidelineName && compactChipGuidelineName) {\n            if (!chipGuideline.classList.contains('hidden')) {\n                compactChipGuideline.classList.remove('hidden');\n                compactChipGuidelineName.textContent = chipGuidelineName.textContent;\n                if (compactChipsRow) {\n                    compactChipsRow.style.display = 'flex';\n                }\n                if (guidelineBadge && compactGuidelineBadge && !guidelineBadge.classList.contains('hidden')) {\n                    compactGuidelineBadge.classList.remove('hidden');\n                    compactGuidelineBadge.textContent = guidelineBadge.textContent;\n                }\n            } else {\n                compactChipGuideline.classList.add('hidden');\n            }\n        }\n\n        // Keep compact prompt empty (user will write adjustments)\n        const compactPromptInput = document.getElementById('compactPromptInput');\n        if (compactPromptInput) {\n            compactPromptInput.value = '';\n        }\n    };\n\n    /**\n     * Append a section header row to the detailed review panel.\n     *\n     * @param {Object} sectionData\n     */\n    const addSectionHeader = (sectionData) => {\n        if (!prvSections) {\n            return;\n        }\n\n        state.totalSections += 1;\n        const metaEl = document.createElement('p');\n        metaEl.className = 'prv-section-meta';\n        metaEl.textContent = sectionData.activity_count !== null && sectionData.activity_count !== undefined\n            ? formatTemplate(texts.courseai_section_progress_with_total, {\n                done: 0,\n                total: sectionData.activity_count,\n                description: sectionData.description || '',\n            })\n            : formatTemplate(texts.courseai_section_progress_no_total, {\n                description: sectionData.description || '',\n            });\n\n        const body = document.createElement('div');\n        body.className = 'prv-section-body';\n        body.style.display = 'flex';\n\n        const chevronEl = document.createElement('span');\n        chevronEl.className = 'prv-chevron prv-chevron--open';\n        chevronEl.innerHTML = [\n            '<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\"',\n            'stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"',\n            'stroke-linejoin=\"round\" aria-hidden=\"true\">',\n            '<polyline points=\"9 18 15 12 9 6\"/></svg>'\n        ].join(' ');\n\n        const btn = document.createElement('button');\n        btn.type = 'button';\n        btn.className = 'prv-section-btn';\n        btn.innerHTML = `<span class=\"prv-section-badge\">${state.totalSections}</span>`;\n\n        const infoDiv = document.createElement('div');\n        infoDiv.className = 'prv-section-info';\n        const titleEl = document.createElement('p');\n        titleEl.className = 'prv-section-title';\n        titleEl.textContent = sectionData.name || texts.courseai_plan_default_unnamed;\n        infoDiv.appendChild(titleEl);\n        infoDiv.appendChild(metaEl);\n        btn.appendChild(infoDiv);\n        btn.appendChild(chevronEl);\n        btn.addEventListener('click', () => {\n            const isOpen = body.style.display !== 'none';\n            body.style.display = isOpen ? 'none' : 'flex';\n            chevronEl.classList.toggle('prv-chevron--open', !isOpen);\n        });\n\n        const row = document.createElement('div');\n        row.className = 'prv-section-row';\n        row.appendChild(btn);\n        row.appendChild(body);\n        prvSections.appendChild(row);\n\n        state.planSectionsData.push({\n            sectionIndex: sectionData.section_index,\n            name: sectionData.name || texts.courseai_plan_default_unnamed,\n            description: sectionData.description || '',\n            activityCount: sectionData.activity_count,\n            activities: [],\n            metaEl,\n            bodyEl: body,\n            chevronEl\n        });\n\n        if (prvHeaderSub) {\n            prvHeaderSub.textContent = formatTemplate(texts.courseai_section_label, {\n                section: state.totalSections,\n                name: sectionData.name || texts.courseai_plan_default_unnamed,\n            });\n        }\n        if (planReviewCard) {\n            planReviewCard.style.display = '';\n        }\n    };\n\n    // Build shared render context for submodule helpers\n    const renderCtx = {state, elements, activityLabels, getActivityIconUrl, escapeHtml, texts, formatTemplate, setProgress};\n\n    return {\n        addPlanSection: (section) => addPlanSection(section, renderCtx),\n        addSectionHeader,\n        addActivityToSection: (data) => addActivityToSection(data, renderCtx),\n        showReviewActions: (mode) => showReviewActions(mode, {\n            elements, texts, setProgress,\n            setCompactChatState: setCompactChatStateImpl, deps,\n            syncCompactChatState,\n        }),\n        syncCompactChatState,\n    };\n};\n"],"names":["deps","state","elements","activityLabels","getActivityIconUrl","escapeHtml","setProgress","texts","formatTemplate","prvSections","prvHeaderSub","planReviewCard","syncCompactChatState","langSelect","document","getElementById","compactLangSelect","value","btnWithImages","btnCompactWithImages","imgToggleTrack","compactImgToggleTrack","checked","parentElement","classList","add","remove","btnWithSubsections","btnCompactWithSubsections","subToggleTrack","compactSubToggleTrack","chipSyllabus","compactChipSyllabus","chipSyllabusName","compactChipSyllabusName","compactChipsRow","contains","textContent","style","display","chipGuideline","compactChipGuideline","chipGuidelineName","compactChipGuidelineName","guidelineBadge","compactGuidelineBadge","compactPromptInput","renderCtx","addPlanSection","section","addSectionHeader","sectionData","totalSections","metaEl","createElement","className","activity_count","undefined","courseai_section_progress_with_total","done","total","description","courseai_section_progress_no_total","body","chevronEl","innerHTML","join","btn","type","infoDiv","titleEl","name","courseai_plan_default_unnamed","appendChild","addEventListener","isOpen","toggle","row","planSectionsData","push","sectionIndex","section_index","activityCount","activities","bodyEl","courseai_section_label","addActivityToSection","data","showReviewActions","mode","setCompactChatState","setCompactChatStateImpl"],"mappings":"mbAqCiCA,aACvBC,MACFA,MADEC,SAEFA,SAFEC,eAGFA,eAHEC,mBAIFA,mBAJEC,WAKFA,WALEC,YAMFA,YANEC,MAOFA,MAPEC,eAQFA,gBACAR,MAEES,YACFA,YADEC,aAEFA,aAFEC,eAGFA,gBACAT,SAKEU,qBAAuB,WAEnBC,WAAaC,SAASC,eAAe,cACrCC,kBAAoBF,SAASC,eAAe,qBAC9CF,YAAcG,oBACdA,kBAAkBC,MAAQJ,WAAWI,aAInCC,cAAgBJ,SAASC,eAAe,iBACxCI,qBAAuBL,SAASC,eAAe,wBAC/CK,eAAiBN,SAASC,eAAe,kBACzCM,sBAAwBP,SAASC,eAAe,yBAClDG,eAAiBC,uBACjBA,qBAAqBG,QAAUJ,cAAcI,QACzCD,uBAAyBD,iBACrBF,cAAcI,QACdD,sBAAsBE,cAAcC,UAAUC,IAAI,MAElDJ,sBAAsBE,cAAcC,UAAUE,OAAO,cAM3DC,mBAAqBb,SAASC,eAAe,sBAC7Ca,0BAA4Bd,SAASC,eAAe,6BACpDc,eAAiBf,SAASC,eAAe,kBACzCe,sBAAwBhB,SAASC,eAAe,yBAClDY,oBAAsBC,4BACtBA,0BAA0BN,QAAUK,mBAAmBL,QACnDQ,uBAAyBD,iBACrBF,mBAAmBL,QACnBQ,sBAAsBP,cAAcC,UAAUC,IAAI,MAElDK,sBAAsBP,cAAcC,UAAUE,OAAO,cAM3DK,aAAejB,SAASC,eAAe,gBACvCiB,oBAAsBlB,SAASC,eAAe,uBAC9CkB,iBAAmBnB,SAASC,eAAe,oBAC3CmB,wBAA0BpB,SAASC,eAAe,2BAClDoB,gBAAkBrB,SAASC,eAAe,mBAC5CgB,cAAgBC,qBAAuBC,kBAAoBC,0BACtDH,aAAaP,UAAUY,SAAS,UAOjCJ,oBAAoBR,UAAUC,IAAI,WANlCO,oBAAoBR,UAAUE,OAAO,UACrCQ,wBAAwBG,YAAcJ,iBAAiBI,YACnDF,kBACAA,gBAAgBG,MAAMC,QAAU,gBAQtCC,cAAgB1B,SAASC,eAAe,iBACxC0B,qBAAuB3B,SAASC,eAAe,wBAC/C2B,kBAAoB5B,SAASC,eAAe,qBAC5C4B,yBAA2B7B,SAASC,eAAe,4BACnD6B,eAAiB9B,SAASC,eAAe,kBACzC8B,sBAAwB/B,SAASC,eAAe,yBAClDyB,eAAiBC,sBAAwBC,mBAAqBC,2BACzDH,cAAchB,UAAUY,SAAS,UAWlCK,qBAAqBjB,UAAUC,IAAI,WAVnCgB,qBAAqBjB,UAAUE,OAAO,UACtCiB,yBAAyBN,YAAcK,kBAAkBL,YACrDF,kBACAA,gBAAgBG,MAAMC,QAAU,QAEhCK,gBAAkBC,wBAA0BD,eAAepB,UAAUY,SAAS,YAC9ES,sBAAsBrB,UAAUE,OAAO,UACvCmB,sBAAsBR,YAAcO,eAAeP,qBAQzDS,mBAAqBhC,SAASC,eAAe,sBAC/C+B,qBACAA,mBAAmB7B,MAAQ,KAyF7B8B,UAAY,CAAC9C,MAAAA,MAAOC,SAAAA,SAAUC,eAAAA,eAAgBC,mBAAAA,mBAAoBC,WAAAA,WAAYE,MAAAA,MAAOC,eAAAA,eAAgBF,YAAAA,mBAEpG,CACH0C,eAAiBC,UAAY,0BAAeA,QAASF,WACrDG,iBApFsBC,kBACjB1C,mBAILR,MAAMmD,eAAiB,QACjBC,OAASvC,SAASwC,cAAc,KACtCD,OAAOE,UAAY,mBACnBF,OAAOhB,YAA6C,OAA/Bc,YAAYK,qBAA0DC,IAA/BN,YAAYK,eAClEhD,eAAeD,MAAMmD,qCAAsC,CACzDC,KAAM,EACNC,MAAOT,YAAYK,eACnBK,YAAaV,YAAYU,aAAe,KAE1CrD,eAAeD,MAAMuD,mCAAoC,CACvDD,YAAaV,YAAYU,aAAe,WAG1CE,KAAOjD,SAASwC,cAAc,OACpCS,KAAKR,UAAY,mBACjBQ,KAAKzB,MAAMC,QAAU,aAEfyB,UAAYlD,SAASwC,cAAc,QACzCU,UAAUT,UAAY,gCACtBS,UAAUC,UAAY,CAClB,8DACA,kEACA,8CACA,6CACFC,KAAK,WAEDC,IAAMrD,SAASwC,cAAc,UACnCa,IAAIC,KAAO,SACXD,IAAIZ,UAAY,kBAChBY,IAAIF,oDAA+ChE,MAAMmD,+BAEnDiB,QAAUvD,SAASwC,cAAc,OACvCe,QAAQd,UAAY,yBACde,QAAUxD,SAASwC,cAAc,KACvCgB,QAAQf,UAAY,oBACpBe,QAAQjC,YAAcc,YAAYoB,MAAQhE,MAAMiE,8BAChDH,QAAQI,YAAYH,SACpBD,QAAQI,YAAYpB,QACpBc,IAAIM,YAAYJ,SAChBF,IAAIM,YAAYT,WAChBG,IAAIO,iBAAiB,SAAS,WACpBC,OAAgC,SAAvBZ,KAAKzB,MAAMC,QAC1BwB,KAAKzB,MAAMC,QAAUoC,OAAS,OAAS,OACvCX,UAAUxC,UAAUoD,OAAO,qBAAsBD,iBAG/CE,IAAM/D,SAASwC,cAAc,OACnCuB,IAAItB,UAAY,kBAChBsB,IAAIJ,YAAYN,KAChBU,IAAIJ,YAAYV,MAChBtD,YAAYgE,YAAYI,KAExB5E,MAAM6E,iBAAiBC,KAAK,CACxBC,aAAc7B,YAAY8B,cAC1BV,KAAMpB,YAAYoB,MAAQhE,MAAMiE,8BAChCX,YAAaV,YAAYU,aAAe,GACxCqB,cAAe/B,YAAYK,eAC3B2B,WAAY,GACZ9B,OAAAA,OACA+B,OAAQrB,KACRC,UAAAA,YAGAtD,eACAA,aAAa2B,YAAc7B,eAAeD,MAAM8E,uBAAwB,CACpEpC,QAAShD,MAAMmD,cACfmB,KAAMpB,YAAYoB,MAAQhE,MAAMiE,iCAGpC7D,iBACAA,eAAe2B,MAAMC,QAAU,KAUnC+C,qBAAuBC,OAAS,gCAAqBA,KAAMxC,WAC3DyC,kBAAoBC,OAAS,oCAAkBA,KAAM,CACjDvF,SAAAA,SAAUK,MAAAA,MAAOD,YAAAA,YACjBoF,oBAAqBC,iCAAyB3F,KAAAA,KAC9CY,qBAAAA,uBAEJA,qBAAAA"}
